using System.Net;using System.Text;using SalekhPos.Desktop.Infrastructure.Management;using Xunit;namespace SalekhPos.Desktop.Tests;public sealed class SubscriptionManagerHttpTests{[Fact]public async Task LoadsPlans(){var o=Guid.NewGuid(),id=Guid.NewGuid();using var c=Client(_=>Json($$"""[{"planId":"{{id:D}}","code":"starter","name":"Starter","price":19,"currency":"GEL","interval":"monthly","entitlements":{"stores":1},"active":true}]"""));var p=await new HttpSubscriptionManager(c).PlansAsync(o,default);Assert.Single(p);Assert.Equal(1,p[0].Entitlements["stores"]);}private static HttpClient Client(Func<HttpRequestMessage,HttpResponseMessage> f)=>new(new H(f)){BaseAddress=new("https://pos.test/")};private static HttpResponseMessage Json(string x)=>new(HttpStatusCode.OK){Content=new StringContent(x,Encoding.UTF8,"application/json")};private sealed class H(Func<HttpRequestMessage,HttpResponseMessage> f):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct)=>Task.FromResult(f(r));}}